describe("FE-1 exactly one useOnboardingBoard() call site (the parent page)", () => {
  // NOTE: this was originally written as toHaveBeenCalledTimes(1) after the
  // click below, which is untestable by construction -- clicking "Start
  // Onboarding" runs setOnboarding(true), a state update inside
  // OnboardingRenewalPage itself, which forces React to re-run the whole
  // component body on the next render and therefore re-invoke every hook
  // called there, including useOnboardingBoard(). That's normal React
  // behavior for a hook called unconditionally in the render body, not a
  // sign that some OTHER call site exists. The real invariant -- "no
  // component other than the page calls this hook" -- is a static,
  // call-count-independent property already covered by the two describe
  // blocks above (OnboardingBoard's "no internal invocation" check, and
  // OnboardingModal's "uses the passed startOnboarding reference, not
  // INTERNAL_HOOK_BOARD's" check). This test instead asserts the dynamic
  // shape that's actually true: exactly 1 call for the initial mount, plus
  // exactly 1 more for the one state-driven re-render the click causes --
  // never a 3rd, which is what a stray extra call site (e.g. inside the
  // modal) would produce.
  it("mounting the page calls the hook once, and opening the modal adds only the page's own one re-render", () => {
    render(<OnboardingRenewalPage />);
    expect(useOnboardingBoard).toHaveBeenCalledTimes(1);
    fireEvent.click(screen.getByRole("button", { name: /start onboarding/i }));
    expect(useOnboardingBoard).toHaveBeenCalledTimes(2);
  });
});
